def diag_runs(rows):
    H=len(rows);W=len(rows[0]); A=[[c=='5' for c in r] for r in rows]
    out=[]
    for dy,dx in [(1,1),(1,-1)]:
      lines=[]
      for y in range(H):
       for x in range(W):
        py=y-dy; px=x-dx
        if 0<=py<H and 0<=px<W: continue
        run=0;cur=[]
        yy,xx=y,x
        while 0<=yy<H and 0<=xx<W:
         if A[yy][xx]:run+=1;cur.append(run)
         else:run=0
         yy+=dy;xx+=dx
        lines.append(max(cur or [0]))
      out.append(lines)
    return out
for m in [m1,m2,mt]: print(diag_runs(m))

